## Code Example
```javascript
// Pseudo dedupe check against Firestore
async function isDuplicate(eventId, tenantId) {
  const doc = await Firestore.collection('dedup').doc(`${tenantId}_${eventId}`).get();
  if (doc.exists) return true;
  await Firestore.collection('dedup').doc(`${tenantId}_${eventId}`).set({ seenAt: Date.now() });
  return false;
}
```

